     1	import React, { useMemo, createContext, useContext } from "react";
     2	
     3	import { createBatchingExecutor } from "@graphql-tools/batch-execute";
     4	import { AsyncExecutor, ExecutionResult } from "@graphql-tools/utils";
     5	import { TypedDocumentNode } from "@graphql-typed-document-node/core";
     6	import { create, windowedFiniteBatchScheduler, Batcher } from "@yornaath/batshit";
     7	import { request } from "graphql-request";
     8	
     9	import { debounceErrorToast } from "utils/debounceErrorToast";
    10	import { getGraphqlUrl } from "utils/getGraphqlUrl";
    11	interface IGraphqlBatcher {
    12	  graphqlBatcher: Batcher<any, IQuery>;
    13	}
    14	
    15	interface IQuery {
    16	  id: string;
    17	  document: TypedDocumentNode<any, any>;
    18	  variables: Record<string, any>;
    19	  isDisputeTemplate?: boolean;
    20	  chainId?: number;
    21	}
    22	
    23	const Context = createContext<IGraphqlBatcher | undefined>(undefined);
    24	
    25	const fetch = async <TArgs,>(url: string, document: TypedDocumentNode<unknown, TArgs>, variables?: TArgs) => {
    26	  try {
    27	    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    28	    //@ts-ignore
    29	    const result = request(url, document, variables).then((res) => ({
    30	      data: res,
    31	    })) as Promise<ExecutionResult>;
    32	
    33	    return result;
    34	  } catch (error) {
    35	    console.error("Graph error: ", { error });
    36	    debounceErrorToast("Graph query error: failed to fetch data.");
    37	    return { data: {} };
    38	  }
    39	};
    40	
    41	const coreExecutor: AsyncExecutor = async ({ document, variables }) => {
    42	  return fetch(getGraphqlUrl(false), document, variables);
    43	};
    44	
    45	const dtrExecutor: AsyncExecutor = async ({ document, variables }) => {
    46	  return fetch(getGraphqlUrl(true), document, variables);
    47	};
    48	
    49	const coreBatchExec = createBatchingExecutor(coreExecutor);
    50	const dtrBatchExec = createBatchingExecutor(dtrExecutor);
    51	
    52	const fetcher = async (queries: IQuery[]) => {
    53	  const batchdata = await Promise.all(
    54	    queries.map(({ document, variables, isDisputeTemplate }) =>
    55	      isDisputeTemplate
    56	        ? dtrBatchExec({
    57	            document,
    58	            variables,
    59	          })
    60	        : coreBatchExec({
    61	            document,
    62	            variables,
    63	          })
    64	    )
    65	  );
    66	
    67	  // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    68	  //@ts-ignore
    69	  const processedData = batchdata.map((data, index) => ({ id: queries[index].id, result: data.data }));
    70	  return processedData;
    71	};
    72	
    73	const GraphqlBatcherProvider: React.FC<{ children?: React.ReactNode }> = ({ children }) => {
    74	  const graphqlBatcher = create({
    75	    fetcher,
    76	    resolver: (results, query) => results.find((result) => result.id === query.id)!["result"],
    77	    scheduler: windowedFiniteBatchScheduler({
    78	      windowMs: 100,
    79	      maxBatchSize: 5,
    80	    }),
    81	  });
    82	  return <Context.Provider value={useMemo(() => ({ graphqlBatcher }), [graphqlBatcher])}>{children}</Context.Provider>;
    83	};
    84	
    85	export const useGraphqlBatcher = () => {
    86	  const context = useContext(Context);
    87	  if (!context) {
    88	    throw new Error("Context Provider not found.");
    89	  }
    90	  return context;
    91	};
    92	
    93	export default GraphqlBatcherProvider;
