    64	  disputeTemplate: IDisputeTemplate;
    65	  resetDisputeData: () => void;
    66	  isSubmittingCase: boolean;
    67	  setIsSubmittingCase: (isSubmittingCase: boolean) => void;
    68	  isPolicyUploading: boolean;
    69	  setIsPolicyUploading: (isPolicyUploading: boolean) => void;
    70	  isBatchCreation: boolean;
    71	  setIsBatchCreation: (isBatchCreation: boolean) => void;
    72	  batchSize: number;
    73	  setBatchSize: (batchSize?: number) => void;
