    88	  aliasesArray: [{ name: "", address: "", id: "1" }],
    89	  disputeKitId: DisputeKits.Classic,
    90	  version: "1.0",
    91	});
    92	
    93	const initialDisputeData = getInitialDisputeData();
    94	
    95	const NewDisputeContext = createContext<INewDisputeContext | undefined>(undefined);
    96	
    97	export const useNewDisputeContext = () => {
    98	  const context = useContext(NewDisputeContext);
    99	  if (!context) {
   100	    throw new Error("Context Provider not found.");
   101	  }
   102	  return context;
   103	};
   104	
   105	export const NewDisputeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
   106	  const [disputeData, setDisputeData] = useLocalStorage<IDisputeData>("disputeData", initialDisputeData);
   107	  const [isSubmittingCase, setIsSubmittingCase] = useState<boolean>(false);
   108	  const [isPolicyUploading, setIsPolicyUploading] = useState<boolean>(false);
   109	  const [isBatchCreation, setIsBatchCreation] = useState<boolean>(false);
   110	  const [batchSize, setBatchSize] = useLocalStorage<number>("disputeBatchSize", MIN_DISPUTE_BATCH_SIZE);
   111	  const [selectedFeatures, setSelectedFeatures] = useState<Features[]>([]);
   112	
   113	  const disputeTemplate = useMemo(() => constructDisputeTemplate(disputeData), [disputeData]);
   114	  const location = useLocation();
   115	
   116	  const resetDisputeData = useCallback(() => {
   117	    const freshData = getInitialDisputeData();
   118	    setDisputeData(freshData);
   119	    setBatchSize(MIN_DISPUTE_BATCH_SIZE);
   120	    // eslint-disable-next-line react-hooks/exhaustive-deps
   121	  }, []);
   122	
   123	  useEffect(() => {
   124	    // Cleanup function to clear local storage when user leaves the route
   125	    if (location.pathname.includes("/resolver") || location.pathname.includes("/attachment")) return;
   126	
   127	    resetDisputeData();
   128	    // eslint-disable-next-line react-hooks/exhaustive-deps
   129	  }, [location.pathname]);
   130	
   131	  const contextValues = useMemo(
   132	    () => ({
   133	      disputeData,
   134	      setDisputeData,
   135	      disputeTemplate,
   136	      resetDisputeData,
   137	      isSubmittingCase,
   138	      setIsSubmittingCase,
   139	      isPolicyUploading,
   140	      setIsPolicyUploading,
   141	      isBatchCreation,
   142	      setIsBatchCreation,
   143	      batchSize,
   144	      setBatchSize,
   145	      selectedFeatures,
   146	      setSelectedFeatures,
   147	    }),
   148	    [
   149	      disputeData,
   150	      disputeTemplate,
   151	      resetDisputeData,
   152	      isSubmittingCase,
   153	      isPolicyUploading,
   154	      setDisputeData,
   155	      isBatchCreation,
   156	      setIsBatchCreation,
   157	      batchSize,
   158	      setBatchSize,
   159	      selectedFeatures,
   160	      setSelectedFeatures,
   161	    ]
   162	  );
   163	
   164	  return <NewDisputeContext.Provider value={contextValues}>{children}</NewDisputeContext.Provider>;
   165	};
   166	
   167	const constructDisputeTemplate = (disputeData: IDisputeData) => {
   168	  // eslint-disable-next-line @typescript-eslint/no-unused-vars
   169	  const { courtId, numberOfJurors, arbitrationCost, disputeKitId, ...baseTemplate } = disputeData;
   170	
   171	  if (!isUndefined(baseTemplate.aliasesArray)) {
   172	    baseTemplate.aliasesArray = baseTemplate.aliasesArray.filter((item) => item.address !== "" && item.isValid);
   173	    if (baseTemplate.aliasesArray.length === 0) delete baseTemplate.aliasesArray;
   174	    else {
   175	      const aliases: Alias = {};
   176	
   177	      for (const alias of baseTemplate.aliasesArray) {
   178	        aliases[alias.name] = alias.address;
   179	      }
   180	
   181	      baseTemplate.aliases = aliases;
   182	    }
   183	  }
   184	
   185	  for (const answer of baseTemplate.answers) {
   186	    answer.id = "0x" + BigInt(answer.id).toString(16);
   187	  }
   188	  if (!isUndefined(baseTemplate.policyURI) && isEmpty(baseTemplate.policyURI)) delete baseTemplate.policyURI;
   189	
   190	  baseTemplate.arbitratorAddress = klerosCoreAddress[DEFAULT_CHAIN.id];
   191	  baseTemplate.arbitratorChainID = DEFAULT_CHAIN.id.toString();
   192	
   193	  return baseTemplate as IDisputeTemplate;
   194	};
