     1	import React, { createContext, useContext, useCallback, useEffect, useState } from "react";
     2	
     3	import { useTranslation } from "react-i18next";
     4	
     5	type Language = "en" | "es" | "fr";
     6	
     7	interface LanguageContextValue {
     8	  language: Language;
     9	  changeLanguage: (lang: Language) => void;
    10	}
    11	
    12	const LanguageContext = createContext<LanguageContextValue | undefined>(undefined);
    13	
    14	const SUPPORTED_LANGUAGES: Language[] = ["en", "es", "fr"];
    15	
    16	// Normalize and validate language code
    17	const normalizeLanguage = (lng: string): Language => {
    18	  // Direct match
    19	  if (SUPPORTED_LANGUAGES.includes(lng as Language)) {
    20	    return lng as Language;
    21	  }
    22	
    23	  // Try base language (e.g., "en-US" -> "en")
    24	  const baseLang = lng.split("-")[0];
    25	  if (SUPPORTED_LANGUAGES.includes(baseLang as Language)) {
    26	    return baseLang as Language;
    27	  }
    28	
    29	  // Default to English
    30	  return "en";
    31	};
    32	
    33	export const LanguageProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    34	  const { i18n } = useTranslation();
    35	  const [language, setLanguage] = useState<Language>(normalizeLanguage(i18n.language));
    36	
    37	  useEffect(() => {
    38	    // Sync state with i18n language changes
    39	    const handleLanguageChange = (lng: string) => {
    40	      setLanguage(normalizeLanguage(lng));
    41	    };
    42	
    43	    i18n.on("languageChanged", handleLanguageChange);
    44	
    45	    return () => {
    46	      i18n.off("languageChanged", handleLanguageChange);
    47	    };
    48	  }, [i18n]);
    49	
    50	  const changeLanguage = useCallback(
    51	    (lang: Language) => {
    52	      i18n.changeLanguage(lang);
    53	      setLanguage(lang);
    54	    },
    55	    [i18n]
    56	  );
    57	
    58	  return <LanguageContext.Provider value={{ language, changeLanguage }}>{children}</LanguageContext.Provider>;
    59	};
    60	
    61	export const useLanguage = (): LanguageContextValue => {
    62	  const context = useContext(LanguageContext);
    63	  if (!context) {
    64	    throw new Error("useLanguage must be used within a LanguageProvider");
    65	  }
    66	  return context;
    67	};
