    21	
    22	// https://github.com/alchemyplatform/alchemy-sdk-js/blob/c4440cb/src/types/types.ts#L98-L153
    23	const alchemyToViemChain: Record<number, string> = {
    24	  [arbitrumSepolia.id]: "arb-sepolia",
    25	  [arbitrum.id]: "arb-mainnet",
    26	  [mainnet.id]: "eth-mainnet",
    27	  [sepolia.id]: "eth-sepolia",
    28	  [gnosis.id]: "gnosis-mainnet",
    29	  [gnosisChiado.id]: "gnosis-chiado",
    30	};
    31	
    32	type AlchemyProtocol = "https" | "wss";
    33	
    34	// https://github.com/alchemyplatform/alchemy-sdk-js/blob/c4440cb/src/util/const.ts#L16-L18
    35	function getAlchemyRpcUrl(protocol: AlchemyProtocol, chainId: number | string): string {
    36	  const network = alchemyToViemChain[Number(chainId)];
    37	  if (!network) {
    38	    throw new Error(`Unsupported chain ID: ${chainId}`);
    39	  }
    40	  return `${protocol}://${network}.g.alchemy.com/v2/${alchemyApiKey}`;
    41	}
    42	
    43	export const alchemyTransport = (chain: AppKitNetwork) =>
    44	  fallback([http(getAlchemyRpcUrl("https", chain.id)), webSocket(getAlchemyRpcUrl("wss", chain.id))]);
    45	export const defaultTransport = (chain: AppKitNetwork) =>
    46	  fallback([http(chain.rpcUrls.default?.http?.[0]), webSocket(chain.rpcUrls.default?.webSocket?.[0])]);
    47	
    48	export const getChainRpcUrl = (protocol: AlchemyProtocol, chainId: number | string) => {
    49	  return getAlchemyRpcUrl(protocol, chainId);
    50	};
    51	
    52	export const getDefaultChainRpcUrl = (protocol: AlchemyProtocol) => {
    53	  return getChainRpcUrl(protocol, DEFAULT_CHAIN.id);
    54	};
    55	
    56	const isProduction = isProductionDeployment();
    57	const isLocalhost = isLocalDeployment();
    58	
    59	const getTransports = () => {
    60	  const commonTransports = {
    61	    [isProduction ? gnosis.id : gnosisChiado.id]: isProduction
    62	      ? defaultTransport(gnosis)
    63	      : defaultTransport(gnosisChiado),
    64	    [mainnet.id]: alchemyTransport(mainnet), // Always enabled for ENS resolution
    65	  };
    66	
    67	  if (isLocalhost)
    68	    return {
    69	      [hardhat.id]: http(HARDHAT_NODE_RPC),
    70	      ...commonTransports,
    71	    };
    72	
    73	  return {
    74	    [isProduction ? arbitrum.id : arbitrumSepolia.id]: isProduction
    75	      ? alchemyTransport(arbitrum)
    76	      : alchemyTransport(arbitrumSepolia),
    77	    ...commonTransports,
