const TAB_PATHS = ["stakes/1", "cases/1/desc/all", "votes/1/desc/all"];

const getTabIndex = (currentPath: string) => {
  return TAB_PATHS.findIndex((path) => currentPath.includes(path.split("/")[0]));
};

const Profile: React.FC = () => {
  const { t } = useTranslation();
  const { isConnected, address: connectedAddress } = useAccount();
  const [searchParams] = useSearchParams();
  const { pathname } = useLocation();
  const navigate = useNavigate();
  const rawAddress = searchParams.get("address")?.toLowerCase();
  const searchParamAddress = rawAddress && isAddress(rawAddress) ? rawAddress : undefined;

  const TABS = useMemo(
    () => [
      { text: t("navigation.stakes"), value: 0, Icon: PnkIcon, path: TAB_PATHS[0] },
      { text: t("navigation.cases"), value: 1, Icon: DocIcon, path: TAB_PATHS[1] },
      { text: t("stats.votes"), value: 2, Icon: VotedIcon, path: TAB_PATHS[2] },
    ],
    [t]
  );

  useEffect(() => {
    if (isConnected && !searchParamAddress && connectedAddress) {
      navigate(`${pathname}?address=${connectedAddress.toLowerCase()}`, { replace: true });
    }
  }, [isConnected, searchParamAddress, connectedAddress, pathname, navigate]);

  const handleTabChange = (tabIndex: number) => {
    const selectedTab = TABS[tabIndex];
    const basePath = `/profile/${selectedTab.path}`;
    const queryParam = searchParamAddress ? `?address=${searchParamAddress}` : "";
    navigate(`${basePath}${queryParam}`);
  };

  return (
    <Container>
      {searchParamAddress ? (
        <>
          <JurorCard {...{ searchParamAddress }} />
          <StyledTabs
            currentValue={getTabIndex(pathname)}
            items={TABS}
            callback={(tabIndex: number) => handleTabChange(tabIndex)}
          />
          <Routes>
            <Route path="stakes/:page" element={<Stakes {...{ searchParamAddress }} />} />
            <Route path="cases/:page/:order/:filter" element={<Cases {...{ searchParamAddress }} />} />
            <Route path="votes/:page/:order/:filter" element={<Votes {...{ searchParamAddress }} />} />
            <Route
              path="*"
              element={
                <Navigate
                  to={`${searchParamAddress ? `stakes/1?address=${searchParamAddress}` : "stakes/1"}`}
                  replace
                />
              }
            />
          </Routes>
        </>
      ) : !isConnected ? (
        <ConnectWalletContainer>
          {t("profile.to_see_profile_connect")}
          <hr />
          <ConnectWallet />
        </ConnectWalletContainer>
      ) : null}
      <FavoriteCases />
      <ScrollTop />
    </Container>
  );
};

export default Profile;
import React from "react";
import styled, { css } from "styled-components";

import { useTranslation } from "react-i18next";
import { Navigate, Route, Routes, useLocation } from "react-router-dom";
import { useToggle } from "react-use";
import { useAccount } from "wagmi";

import { useAtlasProvider } from "@kleros/kleros-app";

import { MAX_WIDTH_LANDSCAPE, landscapeStyle } from "styles/landscapeStyle";
import { responsiveSize } from "styles/responsiveSize";

import ConnectWallet from "components/ConnectWallet";
import EnsureAuth from "components/EnsureAuth";
import HeroImage from "components/HeroImage";
import HowItWorks from "components/HowItWorks";
import Resolver from "components/Popup/MiniGuides/DisputeResolver";
import ScrollTop from "components/ScrollTop";

import Description from "./Briefing/Description";
import Title from "./Briefing/Title";
import Landing from "./Landing";
import Category from "./Parameters/Category";
import Court from "./Parameters/Court";
import Jurors from "./Parameters/Jurors";
import NotablePersons from "./Parameters/NotablePersons";
import VotingOptions from "./Parameters/VotingOptions";
import Policy from "./Policy";
import Preview from "./Preview";
import Timeline from "./Timeline";

const Wrapper = styled.div`
  width: 100%;
`;

const Container = styled.div`
  display: flex;
  flex-direction: column;
  gap: 32px;
  width: 100%;
  background-color: ${({ theme }) => theme.lightBackground};
  padding: ${responsiveSize(24, 32)};
  padding-top: ${responsiveSize(24, 28)};
  padding-bottom: ${responsiveSize(76, 96)};
  max-width: ${MAX_WIDTH_LANDSCAPE};
  margin: 0 auto;
`;

const ConnectWalletContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  color: ${({ theme }) => theme.primaryText};
`;

const StyledEnsureAuth = styled(EnsureAuth)`
  align-self: center;
`;
`;

const HowItWorksAndTimeline = styled.div`
  display: none;

  ${landscapeStyle(
    () => css`
      display: flex;
      flex-direction: column;
      position: absolute;
      left: 2%;
      gap: 40px;
    `
  )}
`;

const MiddleContentContainer = styled.div`
  display: flex;
  justify-content: center;
  position: relative;
`;

const Heading = styled.h1`
  margin: 0;
  font-size: 24px;
  font-weight: 600;
  color: ${({ theme }) => theme.primaryText};
  text-align: center;
`;

const Paragraph = styled.p`
  padding: 0;
  margin: 0;
  font-size: 16px;
  text-align: center;
  color: ${({ theme }) => theme.secondaryText};
`;

const DisputeResolver: React.FC = () => {
  const { t } = useTranslation();
  const location = useLocation();
  const [isDisputeResolverMiniGuideOpen, toggleDisputeResolverMiniGuide] = useToggle(false);
  const { isVerified } = useAtlasProvider();
  const { isConnected } = useAccount();
  const isPreviewPage = location.pathname.includes("/preview");

  return (
    <Wrapper>
      <HeroImage />
      <Container>
        {!isConnected || !isVerified ? (
          <>
            <Heading>{t("resolver.justice_as_service")}</Heading>
            <Paragraph>{t("resolver.send_disputes_get_decisions")}</Paragraph>
          </>
        ) : null}
        {isConnected ? (
          <StyledEnsureAuth buttonText={t("wallet.sign_in_to_start")}>
            <MiddleContentContainer>
              {isConnected && !isPreviewPage ? (
                <HowItWorksAndTimeline>
                  <HowItWorks
                    isMiniGuideOpen={isDisputeResolverMiniGuideOpen}
                    toggleMiniGuide={toggleDisputeResolverMiniGuide}
                    MiniGuideComponent={Resolver}
                  />
                  <Timeline />
                </HowItWorksAndTimeline>
              ) : null}
              <Routes>
                <Route index element={<Navigate to="create" replace />} />
                <Route path="/create/*" element={<Landing />} />
                <Route path="/title/*" element={<Title />} />
                <Route path="/description/*" element={<Description />} />
                <Route path="/court/*" element={<Court />} />
                <Route path="/category/*" element={<Category />} />
                <Route path="/jurors/*" element={<Jurors />} />
                <Route path="/voting-options/*" element={<VotingOptions />} />
                <Route path="/notable-persons/*" element={<NotablePersons />} />
                <Route path="/policy/*" element={<Policy />} />
                <Route path="/preview/*" element={<Preview />} />
              </Routes>
            </MiddleContentContainer>
          </StyledEnsureAuth>
        ) : (
          <ConnectWalletContainer>
            {t("resolver.to_create_dispute_connect")}
            <hr />
            <ConnectWallet />
          </ConnectWalletContainer>
        )}
      </Container>
      <ScrollTop />
    </Wrapper>
  );
};

export default DisputeResolver;

